28	$resolvedLogs=(Resolve-Path -LiteralPath $LogDirectory).Path
29	$gitRoot=$resolvedRoot
30	if ($Probe) {
31	    if ($Writer -or $ConclusionOnly -or $Resume -or $ReadDirectory -or $Model -ne 'deepseek-v4-pro' -or $Seat -ne 'probe' -or $MaxTurns -ne 12 -or $WatchdogSeconds -ne 300) { throw 'Probe role/budget binding invalid' }
32	    $expected='C:/Users/june/AppData/Local/Temp/agent-coop-isolated-workflow-20261010/permission-profile-20261011/probe-02/workspace'
33	    if ($resolvedRoot.Replace('\','/') -ne $expected) { throw 'Probe fixture binding invalid' }
34	    $gitRoot=(Resolve-Path -LiteralPath $BaselineRoot).Path
35	}
36	$readArgs=@()
37	if ($ReadDirectory) { $readArgs=@('--add-dir',(Resolve-Path -LiteralPath $ReadDirectory).Path) }
38	$toolArgs=@('--tools','Read,Glob,Grep','--allowedTools','Read,Glob,Grep')
39	if ($ConclusionOnly) { $toolArgs=@('--tools','') }
40	$permissionArgs=@()
41	if ($Probe) {
42	    $probeRoot=$resolvedRoot.Replace('\','/')
43	    $toolArgs=@('--tools','Read,Glob,Grep,Write,Edit','--allowedTools','Read','Glob','Grep',"Write($probeRoot/write-ok.txt)","Edit($probeRoot/edit-ok.txt)",'--disallowedTools','Bash','PowerShell')
44	    $permissionArgs=@('--permission-mode','dontAsk','--setting-sources','none','--no-session-persistence')
45	}
46	if ($Writer) {
47	    if ($Model -ne 'deepseek-v4-pro' -or $Seat -notin @('p1','p3','p7') -or $ConclusionOnly -or $Resume -or $ReadDirectory -or -not $AdmissionEvidence -or -not $WriteFiles.Count) { throw 'Bound writer role/profile required; obsolete acceptEdits branch disabled' }
48	    $admission=Get-Content -LiteralPath $AdmissionEvidence -Raw|ConvertFrom-Json
49	    if ($admission.status -ne 'admitted after dual confirmation and native plan supervision' -or $admission.candidate -ne $Candidate -or $admission.root -ne $resolvedRoot.Replace('\','/') -or $admission.session -ne $Session) { throw 'Writer admission binding mismatch' }
50	    if (($WriteFiles -join "`n") -cne ($admission.write_files -join "`n")) { throw 'Writer exact write-set mismatch' }
51	    foreach($name in @('CODEBUDDY_DISABLE_AUTO_MEMORY','CODEBUDDY_CODE_DISABLE_AUTO_MEMORY','CODEBUDDY_MEMORY_EXTRACTION_ENABLED','CODEBUDDY_MEMORY_EXTRACTION_DISABLED')) {
52	        if ([Environment]::GetEnvironmentVariable($name) -ne $admission.environment.$name) { throw 'Writer environment mismatch' }
53	    }
54	    foreach($target in $WriteFiles) {
55	        if (-not [IO.Path]::IsPathFullyQualified($target) -or $target -match '[*?]') { throw 'Writer path must be exact absolute file' }
56	        $walk=[IO.Path]::GetFullPath($target)
57	        while($walk) {
58	            if(Test-Path -LiteralPath $walk) {
59	                $item=Get-Item -LiteralPath $walk -Force
60	                if($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Writer reparse path rejected' }
61	            }
62	            $next=[IO.Path]::GetDirectoryName($walk)
63	            if($next -eq $walk){break};$walk=$next
64	        }
65	        if(Test-Path -LiteralPath $target -PathType Leaf) {
66	            $linkCount=& $node -e 'console.log(require("fs").lstatSync(process.argv[1]).nlink)' $target
67	            if($LASTEXITCODE -ne 0 -or $linkCount -ne '1') { throw 'Writer hardlink count rejected' }
68	        }
69	    }
70	    foreach($file in $admission.existing_files) {
71	        if((Get-FileHash -LiteralPath $file.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256) { throw 'Writer target hash drift' }
72	    }
73	    $rules=@('Read','Glob','Grep')
74	    foreach($target in $WriteFiles){$rules+=@("Write($target)","Edit($target)")}
75	    $toolArgs=@('--tools','Read,Glob,Grep,Write,Edit','--allowedTools')+$rules+@('--disallowedTools','Bash','PowerShell')
76	    $permissionArgs=@('--permission-mode','dontAsk','--setting-sources','none','--no-session-persistence')
77	}
78	Set-Location -LiteralPath $resolvedRoot
79	$head=(& git -C $gitRoot rev-parse HEAD).Trim()
80	if ($LASTEXITCODE -ne 0 -or $head -ne $Candidate) { throw 'Review HEAD does not match exact candidate' }
81	$status=@(& git -C $gitRoot status --porcelain --untracked-files=all)
82	if ($LASTEXITCODE -ne 0) { throw 'Cannot inspect worktree status' }
83	if ($status.Count) {
