87	    foreach($property in $handoff.changed_files.PSObject.Properties) {
88	        if ((Get-FileHash -LiteralPath (Join-Path $resolvedRoot $property.Name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $property.Value) { throw 'Handoff file drift' }
89	    }
90	}
91	$prompt=[IO.File]::ReadAllText($resolvedPrompt)
92	if ($prompt -match '\{\{[A-Z_]+\}\}' -or -not $prompt.Contains($Candidate)) { throw 'Review prompt unresolved or missing candidate' }
93	if (($Seat -eq 'glm' -and $Model -ne 'glm-5.3') -or ($Seat -eq 'kimi' -and $Model -ne 'kimi-k3-2')) { throw 'Review seat/model mismatch' }
94	$callKind=$(if($Probe){'probe'}elseif($Writer){'repair'}else{'review'})
95	$prefix=Join-Path $resolvedLogs "$callKind-$Gate-$Seat-r$Round"
96	foreach ($suffix in @('.jsonl','.stderr.txt','.invocation.json','.completion.json')) {
97	    if (Test-Path -LiteralPath ($prefix+$suffix)) { throw "Existing receipt must not be overwritten: $prefix$suffix" }
98	}
99	$start=[DateTimeOffset]::UtcNow
100	$metadata=[ordered]@{
101	    root=$resolvedRoot; candidate=$Candidate; model=$Model; seat=$Seat; requested_session=$Session
102	    resume=$Resume; round=$Round; prompt=$resolvedPrompt; additional_read_directory=$ReadDirectory
103	    prompt_sha256=(Get-FileHash -LiteralPath $resolvedPrompt -Algorithm SHA256).Hash.ToLowerInvariant()
104	    started_at=$start.ToString('o'); max_turns=$MaxTurns; tools=$(if($Writer -or $Probe){'Read,Glob,Grep,Write,Edit'}elseif($ConclusionOnly){'none'}else{'Read,Glob,Grep'})
105	    handoff_manifest=$HandoffManifest
106	    admission_evidence=$(if($AdmissionEvidence){Get-Content -LiteralPath $AdmissionEvidence -Raw | ConvertFrom-Json}else{$null})
107	    purpose=$callKind; permission_mode=$(if($Probe -or $Writer){'dontAsk'}else{'default'})
108	    exact_write_files=$WriteFiles
109	    strict_mcp_empty=$true; wall_clock_watchdog="dispatcher ${WatchdogSeconds}s; not enforced by this wrapper"
110	}
111	if ($Resume) { $sessionArgs=@('--resume',$Resume) } else { $sessionArgs=@('--session-id',$Session) }
112	$actualArgs=@($entry,'-p',$prompt,'--model',$Model)+$sessionArgs+$readArgs+$toolArgs+$permissionArgs+@('--strict-mcp-config','--mcp-config','{"mcpServers":{}}','--max-turns',[string]$MaxTurns,'--output-format','stream-json','--verbose')
113	$argumentJson=ConvertTo-Json -InputObject $actualArgs -Compress
114	$metadata.actual_argv=$actualArgs
115	$metadata.actual_argv_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($argumentJson))).ToLowerInvariant()
116	$metadata.argv_hash_encoding='UTF-8 PowerShell ConvertTo-Json -Compress array, no newline'
117	$metadata.baseline_root=$gitRoot
118	$metadata | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath ($prefix+'.invocation.json') -Encoding utf8
119	& $node @actualArgs 1> ($prefix+'.jsonl') 2> ($prefix+'.stderr.txt')
120	$callExit=$LASTEXITCODE
121	$finish=[DateTimeOffset]::UtcNow
122	[ordered]@{
123	    candidate=$Candidate; exit_code=$callExit; finished_at=$finish.ToString('o')
124	    wall_seconds=($finish-$start).TotalSeconds
125	    final_head=(& git -C $gitRoot rev-parse HEAD).Trim()
126	    final_status=@(& git -C $gitRoot status --porcelain --untracked-files=all)
127	} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath ($prefix+'.completion.json') -Encoding utf8
128	exit $callExit\r

